<script setup lang="ts">import{onBeforeUnmount,onMounted,ref,watch}from"vue";import*as echarts from"echarts";const p=defineProps<{labels:string[];values:number[]}>();const el=ref<HTMLElement>();let c:echarts.ECharts|undefined,o:ResizeObserver|undefined;const draw=()=>c?.setOption({grid:{left:12,right:24,top:12,bottom:12,containLabel:true},xAxis:{type:'value',max:100,splitLine:{lineStyle:{color:'#e5ece8'}}},yAxis:{type:'category',data:p.labels,axisLine:{show:false},axisTick:{show:false}},series:[{type:'bar',data:p.values,barWidth:14,itemStyle:{color:'#176b5b',borderRadius:[0,4,4,0]},label:{show:true,position:'right',formatter:'{c}%'}}]});onMounted(()=>{c=echarts.init(el.value!);draw();o=new ResizeObserver(()=>c?.resize());o.observe(el.value!)});watch(()=>[p.labels,p.values],draw,{deep:true});onBeforeUnmount(()=>{o?.disconnect();c?.dispose()});</script><template><div ref="el" class="chart-canvas compact"/></template>
